scripts.code:
Show Custom Dialog [
    "Filtrar publicaciones" ;
    "Selecciona el tipo de publicaciones que deseas ver." ;
    Default Button: “Programadas” ;
    Button 2: “Publicadas” ;
    Button 3: “Con error”
]

If [ Get ( LastMessageChoice ) = 1 ]
    Perform Script [ “04. Filtrar por estado” ; Parameter: "Programado" ]
Else If [ Get ( LastMessageChoice ) = 2 ]
    Perform Script [ “04. Filtrar por estado” ; Parameter: "Publicado" ]
Else If [ Get ( LastMessageChoice ) = 3 ]
    Perform Script [ “04. Filtrar por estado” ; Parameter: "Error" ]
End If

Show Custom Dialog [
    "Cancelar cambios" ;
    "¿Deseas descartar los cambios no guardados?" ;
    Default Button: “Descartar” ;
    Button 2: “Volver”
]

If [ Get ( LastMessageChoice ) = 1 ]
    Revert Record/Request [ With dialog: Off ]
    Set Variable [ $$modoEdicion ; Value: 0 ]
End If

Refresh Window []
